import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { analyzeDiscussion } from "../handlers/analyzeDiscussion";
import type { ApiError } from "../runtime/client";
import type { AnalyzeDiscussionRequest } from "../types/AnalyzeDiscussionRequest";
import type { FeedPartition } from "../types/FeedPartition";
import type { SpaceAnalyzeReportEntityType } from "../types/SpaceAnalyzeReportEntityType";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof analyzeDiscussion>>;
type Vars = { spaceId: SpacePartition; reportId: SpaceAnalyzeReportEntityType; discussionId: FeedPartition; req: AnalyzeDiscussionRequest };

export function useAnalyzeDiscussion(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => analyzeDiscussion(vars.spaceId, vars.reportId, vars.discussionId, vars.req),
    ...options,
  });
}
